import{decompress}from"./codec/deflate.js";import{b64decode}from"./codec/base64.js";import{minifyJS}from"./minify/js.js";const RUNTIME_URL=new URL("data:application/gzip;base64,",import.meta.url);const NET_URL=new URL("data:application/gzip;base64,",import.meta.url);let cached=null,netCached=null;async function bytesOf(url){const s=String(url);if(s.startsWith('data:'))return b64decode(s.slice(s.indexOf(',')+1));const r=await fetch(url);if(!r.ok)throw new Error('bundle '+r.status);return new Uint8Array(await r.arrayBuffer());}
